import SwiftUI
import XCTest

@testable import Kakey

/// `Core/golden/` is the behavior baseline originally generated by the Mac's former Swift implementation. The Mac now uses the Rust
/// core, so this is a read-only check: calling the core through the Mac wrapper layer (placeholder text, error mapping, type
/// conversion) must match the baseline item by item, and the v2 vault, export, and Authenticator backup written by the former
/// implementation must still open. The baseline is not regenerated; to change behavior on purpose, change the Rust implementation
/// and golden together and note it in Core/docs/CHANGELOG.md.
enum Golden {
    static let directory = URL(fileURLWithPath: #filePath)
        .deletingLastPathComponent()  // Tests
        .deletingLastPathComponent()  // Mac
        .deletingLastPathComponent()  // Apple
        .deletingLastPathComponent()  // Repository root
        .appendingPathComponent("Core/golden", isDirectory: true)

    static func object(_ name: String) throws -> [String: Any] {
        let data = try Data(contentsOf: directory.appendingPathComponent("\(name).json"))
        return try XCTUnwrap(JSONSerialization.jsonObject(with: data) as? [String: Any])
    }

    /// Looks up a sample by name in vault.json / authenticator.json.
    static func sample(_ file: String, list: String, name: String) throws -> [String: Any] {
        let samples = try XCTUnwrap(try object(file)[list] as? [[String: Any]])
        return try XCTUnwrap(samples.first { $0["name"] as? String == name }, "\(file).json is missing sample \(name)")
    }
}

final class GoldenVectorTests: XCTestCase {
    private static let goldenDirectory = Golden.directory

    // MARK: - Deterministic vectors

    func testBase32() throws { try check("base32", base32Vectors()) }
    func testTOTP() throws { try check("totp", totpVectors()) }
    func testCanonical() throws { try check("canonical", canonicalVectors()) }
    func testOTPAuth() throws { try check("otpauth", otpauthVectors()) }
    func testSearch() throws { try check("search", searchVectors()) }
    func testPassword() throws { try check("password", passwordVectors()) }

    // MARK: - Samples (files written by the former Mac implementation)

    func testVaultSamples() throws {
        let url = Self.goldenDirectory.appendingPathComponent("vault.json")
        let samples = try XCTUnwrap(JSONSerialization.jsonObject(with: Data(contentsOf: url)) as? [String: Any])
        for sample in try XCTUnwrap(samples["vaults"] as? [[String: Any]]) {
            let data = Data(try XCTUnwrap(sample["file"] as? String).utf8)
            let unlocked = try VaultPersistenceService.unlock(encryptedData: data, password: try XCTUnwrap(sample["password"] as? String))
            try checkAccounts(unlocked.contents, against: sample)
        }
        for sample in try XCTUnwrap(samples["exports"] as? [[String: Any]]) {
            let imported = try importExport(
                try XCTUnwrap(sample["file"] as? String), password: try XCTUnwrap(sample["password"] as? String))
            try checkAccounts(imported, against: sample)
        }
    }

    func testAuthenticatorSamples() throws {
        let url = Self.goldenDirectory.appendingPathComponent("authenticator.json")
        let samples = try XCTUnwrap(JSONSerialization.jsonObject(with: Data(contentsOf: url)) as? [String: Any])
        for sample in try XCTUnwrap(samples["imports"] as? [[String: Any]]) {
            let data = Data(try XCTUnwrap(sample["file"] as? String).utf8)
            let outcome = importOutcome(data: data, password: try XCTUnwrap(sample["password"] as? String))
            XCTAssertEqual(outcome as NSDictionary, try XCTUnwrap(sample["expected"] as? NSDictionary), "\(sample["name"] ?? "")")
        }
    }

    /// Vault and export files written by the Rust core (confirmed at the time to open with the former Mac implementation) must
    /// still open on the Mac.
    func testRustWrittenFilesOpenInSwift() throws {
        let url = Self.goldenDirectory.appendingPathComponent("rust-written.json")
        let samples = try XCTUnwrap(JSONSerialization.jsonObject(with: Data(contentsOf: url)) as? [String: Any])
        let vault = try XCTUnwrap(samples["vault"] as? [String: Any])
        let unlocked = try VaultPersistenceService.unlock(
            encryptedData: Data(try XCTUnwrap(vault["file"] as? String).utf8),
            password: try XCTUnwrap(vault["password"] as? String)
        )
        try checkAccounts(unlocked.contents, against: vault)

        let export = try XCTUnwrap(samples["export"] as? [String: Any])
        let imported = try importExport(try XCTUnwrap(export["file"] as? String), password: try XCTUnwrap(export["password"] as? String))
        try checkAccounts(imported, against: export)
    }

    /// Category format: categories, order, and membership in Rust-written vaults and exports read back unchanged through the app
    /// wrapper.
    func testCategoryFilesOpenInSwift() throws {
        let url = Self.goldenDirectory.appendingPathComponent("categories.json")
        let samples = try XCTUnwrap(JSONSerialization.jsonObject(with: Data(contentsOf: url)) as? [String: Any])
        let vault = try XCTUnwrap(samples["vault"] as? [String: Any])
        let unlocked = try VaultPersistenceService.unlock(
            encryptedData: Data(try XCTUnwrap(vault["file"] as? String).utf8),
            password: try XCTUnwrap(vault["password"] as? String)
        )
        XCTAssertEqual(unlocked.contents.accounts.map(\.id.uuidString), try XCTUnwrap(vault["accountIDs"] as? [String]))
        XCTAssertEqual(unlocked.contents.categories.map(categoryJSON) as NSArray, try XCTUnwrap(vault["categories"] as? NSArray))

        let export = try XCTUnwrap(samples["export"] as? [String: Any])
        let imported = try importExport(try XCTUnwrap(export["file"] as? String), password: try XCTUnwrap(export["password"] as? String))
        XCTAssertEqual(imported.accounts.map(\.id.uuidString), try XCTUnwrap(export["accountIDs"] as? [String]))
        XCTAssertEqual(imported.categories.map(categoryJSON) as NSArray, try XCTUnwrap(export["categories"] as? NSArray))
    }

    /// Older samples have no `categories`: they read as having no categories, with accounts matching field by field.
    private func checkAccounts(_ contents: VaultContents, against sample: [String: Any]) throws {
        let expectedAccounts = try XCTUnwrap(sample["accounts"] as? [[String: Any]])
        XCTAssertTrue(contents.categories.isEmpty, "\(sample["name"] ?? "")")
        XCTAssertEqual(contents.accounts.map(accountJSON) as NSArray, expectedAccounts as NSArray, "\(sample["name"] ?? "")")
    }

    // MARK: - Generation

    private var placeholders: [String: Any] {
        ["unknownIssuer": L10n.tr("Unknown service"), "emptyUsername": L10n.tr("No account")]
    }

    private func base32Vectors() -> [String: Any] {
        let encodeInputs = [
            "", "66", "666f", "666f6f", "666f6f62", "666f6f6261", "666f6f626172", "00", "ff",
            "0001020304050607080910", "3132333435363738393031323334353637383930",
        ]
        let decodeInputs = [
            "MZXW6YTBOI", "mzxw6ytboi", "MZXW 6YTB-OI", "MZXW6YTBOI======", "MZ=XW6", "A", "AB", "ABC",
            "", "  ", "-=", "MZXW1", "MZXW8", "Ä", "GEZDGNBVGY3TQOJQ", "JBSWY3DPEHPK3PXP",
            "jbsw y3dp ehpk 3pxp", "MZXW6YTBOI\n", "\tMZXW6YTBOI", "mzxw6ytboi\u{00A0}",
        ]
        return [
            "encode": encodeInputs.map { hex in ["hex": hex, "base32": coreBase32Encode(data: Data(hex: hex))] },
            "decode": decodeInputs.map { input in ["input": input, "hex": nullable(coreBase32Decode(value: input).map(\.hex))] },
        ]
    }

    private func totpVectors() -> [[String: Any]] {
        let secrets = [
            coreBase32Encode(data: Data("12345678901234567890".utf8)),
            coreBase32Encode(data: Data("12345678901234567890123456789012".utf8)),
            coreBase32Encode(data: Data("1234567890123456789012345678901234567890123456789012345678901234".utf8)),
            "JBSWY3DPEHPK3PXP", "jbsw y3dp ehpk 3pxp", "A", "bad!",
        ]
        let times: [Double] = [0, 59, 1_111_111_109, 1_234_567_890, 2_000_000_000, 20_000_000_000, 1_759_219_200.75, 1_700_000_000.2]
        var vectors: [[String: Any]] = []
        for secret in secrets {
            for algorithm in TOTPAlgorithm.allCases {
                for (digits, period) in [(6, 30), (8, 30), (6, 60), (8, 15)] {
                    for time in times {
                        let account = Account(
                            issuer: "x", username: "y", secret: secret, algorithm: algorithm, digits: digits, period: period)
                        let date = Date(timeIntervalSince1970: time)
                        vectors.append([
                            "secret": secret, "algorithm": algorithm.rawValue, "digits": digits, "period": period, "time": time,
                            "code": TOTPService.code(for: account, date: date),
                            "formatted": TOTPService.formattedCode(for: account, date: date),
                            "secondsRemaining": TOTPService.secondsRemaining(for: account, date: date),
                        ])
                    }
                }
            }
        }
        return vectors
    }

    private func canonicalVectors() -> [String: Any] {
        let cleanInputs = [
            " GitHub%20Inc%0A ", "a%2520b", "a%252520b", "100%", "%E4%BD%A0%E5%A5%BD", "%FF", "\tx\ry\n",
            "  spaced  ", "alex%40example.com", "%3A", "a+b", "\u{00A0}nbsp\u{00A0}", "", "%", "%2", "%zz",
            "%C3%A9t%C3%A9", "line1\nline2", "%0D%0Ax%09",
        ]
        let secretInputs = [
            "MZXW6YTBOI", "mzxw 6ytb-oi", "mzxw%206ytb", "%20", "A", "AB", "bad!", "", "MZXW6YTBOI%0A",
            "jbsw y3dp ehpk 3pxp",
        ]
        let prefixPairs = [
            ("GitHub:alex@example.com", "github"), ("GitHub%3Aalex", "GitHub"), ("GitHub:", "GitHub"),
            ("alex", ""), ("github: alex", "GitHub"), ("Other:alex", "GitHub"), ("GitHub:GitHub:x", "GitHub"),
            (" GitHub:x ", "GitHub "), ("Ärger:x", "ärger"), ("a%3A%20b", "a"),
        ]
        let fieldInputs: [(String, String, String, TOTPAlgorithm, Int, Int)] = [
            ("GitHub", "GitHub:alex", "mzxw 6ytb-oi", .sha1, 6, 30), (" ", "", "MZXW6YTBOI", .sha256, 8, 0),
            ("a", "b", "MZXW6YTBOI", .sha1, 7, 30), ("a", "b", "A", .sha1, 6, 30), ("a%20b", "c%0A", "MZXW6YTBOI", .sha512, 8, -5),
        ]
        let dedupInputs: [(String, String, String, TOTPAlgorithm, Int, Int)] = [
            ("GitHub", "Alex", "mzxw 6ytb-oi", .sha1, 6, 30), (" github ", "alex", "MZXW6YTBOI", .sha1, 6, 30),
            ("", "", "x!", .sha1, 6, 30), ("Café", "ÄBC", "MZXW6YTBOI", .sha512, 8, 60),
        ]
        let issuers = [
            "GitHub", "A&B", "A=B", "A+B", "A B", "A/B", "A?B", "A#B", "A:B", "A@B", "日本", "a%20b", "",
            "O'Reilly", "(x)", "a;b,c", "~_.-", "a!b$c*d", "[x]", "a%b", "a\"b", "a<b>",
        ]
        let usernames = ["alex@example.com", "x:y", "", "a b", "a&b=c"]
        var urls: [[String: Any]] = []
        for issuer in issuers {
            for username in usernames {
                for secret in ["MZXW6YTBOI", "bad!"] {
                    let account = Account(issuer: issuer, username: username, secret: secret, algorithm: .sha256, digits: 8, period: 45)
                    urls.append([
                        "issuer": issuer, "username": username, "secret": secret, "algorithm": "SHA256", "digits": 8,
                        "period": 45, "url": OTPAuthCanonicalizer.otpauthURLString(for: account),
                    ])
                }
            }
        }
        return [
            "placeholders": placeholders,
            "cleanText": cleanInputs.map { ["input": $0, "output": OTPAuthCanonicalizer.cleanText($0)] },
            "standardizedSecret": secretInputs.map { ["input": $0, "output": nullable(OTPAuthCanonicalizer.standardizedSecret($0))] },
            "stripIssuerPrefix": prefixPairs.map { username, issuer in
                [
                    "username": username, "issuer": issuer,
                    "output": coreStrippingIssuerPrefix(username: username, issuer: issuer),
                ]
            },
            "fields": fieldInputs.map { issuer, username, secret, algorithm, digits, period -> [String: Any] in
                let result = coreCanonicalFields(
                    issuer: issuer, username: username, secret: secret, algorithm: algorithm.core,
                    digits: UInt32(clamping: digits), period: UInt32(clamping: period), placeholders: .current)
                return [
                    "issuer": issuer, "username": username, "secret": secret, "algorithm": algorithm.rawValue,
                    "digits": digits, "period": period,
                    "output": nullable(
                        result.map {
                            [
                                "issuer": $0.issuer, "username": $0.username, "secret": $0.secret,
                                "algorithm": TOTPAlgorithm($0.algorithm).rawValue, "digits": Int($0.digits), "period": Int($0.period),
                            ]
                        }),
                ]
            },
            "dedupKey": dedupInputs.map { issuer, username, secret, algorithm, digits, period in
                [
                    "issuer": issuer, "username": username, "secret": secret, "algorithm": algorithm.rawValue,
                    "digits": digits, "period": period,
                    "output": Account.deduplicationKey(
                        issuer: issuer, username: username, secret: secret,
                        algorithm: algorithm, digits: digits, period: period),
                ]
            },
            "otpauthURL": urls,
        ]
    }

    private func otpauthVectors() -> [String: Any] {
        let foobar = Data("foobar".utf8)
        let migrations = [
            migrationURL(
                [
                    .init(secret: foobar, name: "GitHub:alex", issuer: "GitHub", algorithm: 1, digits: 1, type: 2),
                    .init(secret: foobar, name: "hotp", issuer: "X", algorithm: 1, digits: 1, type: 1),
                    .init(secret: foobar, name: "md5", issuer: "Y", algorithm: 4, digits: 1, type: 2),
                    .init(secret: foobar, name: "eight", issuer: "Z", algorithm: 3, digits: 2, type: 2),
                ],
                batch: (2, 1, 7), urlSafe: false),
            migrationURL(
                [
                    .init(secret: foobar, name: "defaults", issuer: "D", algorithm: nil, digits: nil, type: nil),
                    .init(secret: foobar, name: "unspecified", issuer: "U", algorithm: 0, digits: 0, type: 0),
                    .init(secret: Data(), name: "empty", issuer: "E", algorithm: 1, digits: 1, type: 2),
                    .init(secret: Data([0x01, 0x02, 0x03]), name: "", issuer: "", algorithm: 2, digits: 1, type: 2),
                ],
                batch: nil, urlSafe: true),
            migrationURL([], batch: (1, 0, 3), urlSafe: false),
            migrationURL(
                [.init(secret: foobar, name: "bad\u{FFFF}", issuer: "B", algorithm: 1, digits: 1, type: 2, rawName: Data([0xFF, 0xFE]))],
                batch: nil, urlSafe: false),
            "otpauth-migration://offline?data=%%%",
            "otpauth-migration://online?data=CgA%3D",
            "otpauth-migration://offline",
            "otpauth-migration://offline?data=",
        ]
        let singles = [
            "otpauth://totp/GitHub%3Aalex%40example.com?secret=mzxw6ytboi&issuer=GitHub&algorithm=sha256&digits=8&period=60",
            "otpauth://totp/A+B:me?secret=MZXW6YTBOI&issuer=A+B",
            "otpauth://totp/Example:alice@google.com?secret=JBSWY3DPEHPK3PXP&issuer=Example",
            "otpauth://totp/alice@google.com?secret=JBSWY3DPEHPK3PXP",
            "otpauth://totp/ACME%20Co:john.doe@email.com?secret=HXDMVJECJJWSRB3HWIZR4IFUGFTMXBOZ&issuer=ACME%20Co&algorithm=SHA1&digits=6&period=30",
            "otpauth://TOTP/X:y?SECRET=MZXW6YTBOI&Issuer=Z",
            "otpauth://1/X:y?secret=MZXW6YTBOI",
            "otpauth://totp/:y?secret=MZXW6YTBOI",
            "otpauth://totp/X::y?secret=MZXW6YTBOI",
            "otpauth://totp/X:?secret=MZXW6YTBOI",
            "otpauth://totp/?secret=MZXW6YTBOI",
            "otpauth://totp/Issuer:Issuer:acct?secret=MZXW6YTBOI&issuer=Issuer",
            "otpauth://totp/x?secret=MZXW6YTBOI&algorithm=MD5",
            "otpauth://totp/x?secret=MZXW6YTBOI&algorithm=sha512&digits=8",
            "otpauth://totp/x?secret=MZXW6YTBOI&digits=+8",
            "otpauth://totp/x?secret=MZXW6YTBOI&digits=abc",
            "otpauth://totp/x?secret=MZXW6YTBOI&period=-1",
            "otpauth://totp/x?secret=MZXW6YTBOI&period=",
            "otpauth://totp/x?secret=%20",
            "otpauth://totp/x?secret",
            "otpauth://totp/%E6%97%A5%E6%9C%AC:%E5%A4%AA%E9%83%8E?secret=MZXW6YTBOI",
            "otpauth://totp/a%252520b?secret=MZXW6YTBOI",
            "  otpauth://totp/Trim:me?secret=MZXW6YTBOI  ",
            "otpauth://hotp/x?secret=MZXW6YTBOI&counter=1",
            "otpauth://totp/x",
            "otpauth://totp/x?secret=1111",
            "otpauth://totp/x?secret=MZXW6YTBOI&digits=7",
            "otpauth://totp/x?secret=MZXW6YTBOI&period=0",
            "https://example.com/?secret=MZXW6YTBOI",
            "hello",
            "",
            "   ",
        ]
        let lines = [
            "otpauth://totp/A:a?secret=MZXW6YTBOI\n\r\notpauth://totp/B:b?secret=MZXW6YTBOI\n",
            "garbage\n" + migrations[0],
            "\u{2028}otpauth://totp/C:c?secret=MZXW6YTBOI\u{2029}",
        ]
        return [
            "placeholders": placeholders,
            "scan": (singles + migrations).map { input -> [String: Any] in
                let result = OTPAuthParser.parseScanResult(input)
                return [
                    "input": input, "isGoogleMigration": result.isGoogleMigration,
                    "batchKey": nullable(result.batchKey), "accounts": result.accounts.map(parsedJSON),
                ]
            },
            "single": (singles + migrations).map { input in ["input": input, "account": parsedJSON(OTPAuthParser.parse(input))] },
            "lines": lines.map { input in ["input": input, "accounts": OTPAuthParser.parseLines(input).map(parsedJSON)] },
        ]
    }

    private func searchVectors() -> [String: Any] {
        let matchCases: [(String, String, String)] = [
            ("Café Übersicht", "", "cafe"), ("ＧｉｔＨｕｂ", "", "github"), ("GitHub", "alex@example.com", "ALEX EXAMPLE"),
            ("Google", "", "ggl"), ("Google", "", "lgg"), ("x", "y", " "), ("x", "y", ""), ("微软", "", "微"),
            ("Amazon Web Services", "", "aws"), ("GitHub", "", "hub"), ("GitHub", "", "bug"), ("Ｃｏｉｎｂａｓｅ", "", "coin"),
            ("naïve", "", "NAIVE"), ("Straße", "", "strasse"), ("ÅNGSTRÖM", "", "angstrom"), ("x", "user_01", "user01"),
        ]
        let masks = ["alex@example.com", "k@x.io", "@x.io", "13800138000", "123456", "alex", "ka", "k", "", "日本語", "a@b@c"]
        let monograms = ["Google Cloud Platform", "github", "X", "", "  spaced   out ", "日本 語", "ab", "Amazon Web"]
        let palette: [Color] = [.blue, .purple, .orange, .green, .indigo, .pink, .teal, .brown]
        let paletteIssuers = ["GitHub", "Google", "", "日本", "Amazon Web Services", "a", "b", "c", "Microsoft", "Apple"]
        return [
            "matches": matchCases.map { issuer, username, query in
                [
                    "issuer": issuer, "username": username, "query": query,
                    "expected": Account(issuer: issuer, username: username, secret: "MZXW6YTBOI").matchesSearch(query),
                ]
            },
            "mask": masks.map { ["input": $0, "output": SearchIndexService.maskUsername($0)] },
            "monogram": monograms.map { ["input": $0, "output": Account.monogram(for: $0)] },
            "palette": paletteIssuers.map { issuer in
                ["issuer": issuer, "index": palette.firstIndex(of: Account.color(for: issuer)) ?? -1]
            },
        ]
    }

    private func passwordVectors() -> [String: Any] {
        let passwords = [
            "", "abc", "abcdefgh", "ABCDEFGH", "Abcdefgh", "Abcdefgh1", "Abcdefgh1234!", "密码", "密码密码密码密码",
            "12345678", "aB3$", "aaaaaaaaaaaa", "Correct Horse Battery Staple",
            "12345678901", "123456789012", "!@#$%^&*", "abcd1234efgh", "abc123!@", "abc123!@xyz9", "            ", "pässwörd1234",
            "Ａｂｃｄ１２３４", "aaaabbbb", "333333222", "abcdabcd", "AaAaBbBbCcCc", "abcdefga", "aaaa1111",
            "Password1!", "Qwerty123!@#", "Kakey2026!", "vT8#qL2!mZ5@", "q7#Lm2$Vx9", "correcthorsebatterystaple",
        ]
        let filtered = ["Ab1 !~", "密码abc１２３！", "a\tb\nc😀", "Ａｂｃｄ１２３４", "correct horse", "Ab 1", String(repeating: "a", count: 129)]
        return [
            "strength": passwords.map { ["input": $0, "score": PasswordStrength.evaluate($0).rawValue] },
            "filter": filtered.map { ["input": $0, "output": PasswordPolicy.filterInput($0)] },
            "throttle": (0...20).map {
                ["failures": $0, "seconds": nullable(UnlockThrottle.lockoutDuration(afterConsecutiveFailures: $0))]
            },
        ]
    }

    // MARK: - Encoding helpers

    private func accountJSON(_ account: Account) -> [String: Any] {
        [
            "id": account.id.uuidString, "issuer": account.issuer, "username": account.username, "secret": account.secret,
            "algorithm": account.algorithm.rawValue, "digits": account.digits, "period": account.period,
            "createdAt": Int(account.createdAt.timeIntervalSince1970), "addedBy": account.addedBy,
        ]
    }

    private func categoryJSON(_ category: AccountCategory) -> [String: Any] {
        ["id": category.id.uuidString, "name": category.name, "accountIDs": category.accountIDs.map(\.uuidString)]
    }

    /// Import results exclude the random id and import time; pinned entries should be in the Favorites category.
    private func importedAccountJSON(_ account: Account, in contents: VaultContents) -> [String: Any] {
        let favorites = contents.categories.first { $0.name == L10n.tr("Favorites") }
        var json = accountJSON(account)
        json["pinned"] = favorites?.accountIDs.contains(account.id) ?? false
        json.removeValue(forKey: "id")
        json.removeValue(forKey: "createdAt")
        return json
    }

    private func importOutcome(data: Data, password: String) -> [String: Any] {
        do {
            let imported = try ExternalAccountImportService.importAccounts(from: data, password: password)
            return ["accounts": imported.accounts.map { importedAccountJSON($0, in: imported) }]
        } catch let error as ExternalAccountImportError {
            let key: String =
                switch error {
                case .passwordRequired: "err.import.password_required"
                case .invalidFile: "err.import.invalid_file"
                case .wrongPassword: "err.import.wrong_password"
                case .noSupportedAccounts: "err.import.no_supported"
                case .failed: "err.import.failed"
                }
            return ["error": key]
        } catch {
            return ["error": "err.import.invalid_file"]
        }
    }

    private func parsedJSON(_ parsed: ParsedOTPAuth) -> [String: Any] {
        let reasonKeys = [
            "otp.err.bad_url", "otp.err.not_otpauth", "otp.err.not_totp", "otp.err.missing_secret",
            "otp.err.bad_base32", "otp.err.digits", "otp.err.period", "otp.err.bad_migration",
            "otp.err.unsupported_algorithm",
        ]
        let reason = nullable(parsed.reason.map { reason in reasonKeys.first { L10n.tr($0) == reason } ?? "unknown:\(reason)" })
        return [
            "valid": parsed.isValid, "reason": reason, "issuer": parsed.issuer, "account": parsed.account,
            "secret": parsed.secret, "algorithm": parsed.algorithm.rawValue, "digits": parsed.digits, "period": parsed.period,
        ]
    }

    private func importExport(_ file: String, password: String) throws -> VaultContents {
        let url = FileManager.default.temporaryDirectory.appendingPathComponent("Kakey-golden-export-\(UUID().uuidString).json")
        defer { try? FileManager.default.removeItem(at: url) }
        try Data(file.utf8).write(to: url)
        return try ExternalAccountImportService.importAccounts(from: url, password: password)
    }

    private struct MigrationParameter {
        var secret: Data
        var name: String
        var issuer: String
        var algorithm: Int?
        var digits: Int?
        var type: Int?
        var rawName: Data? = nil
    }

    /// Hand-encodes a Google Authenticator migration protobuf (field numbers per the OTPAuthParser decoder).
    private func migrationURL(_ parameters: [MigrationParameter], batch: (size: Int, index: Int, id: Int)?, urlSafe: Bool) -> String {
        func varint(_ value: Int) -> Data {
            var value = UInt64(bitPattern: Int64(value))
            var data = Data()
            repeat {
                var byte = UInt8(value & 0x7f)
                value >>= 7
                if value != 0 { byte |= 0x80 }
                data.append(byte)
            } while value != 0
            return data
        }
        func field(_ number: Int, bytes: Data) -> Data { varint(number << 3 | 2) + varint(bytes.count) + bytes }
        func field(_ number: Int, int: Int?) -> Data { int.map { varint(number << 3) + varint($0) } ?? Data() }

        var payload = Data()
        for parameter in parameters {
            let message =
                field(1, bytes: parameter.secret)
                + field(2, bytes: parameter.rawName ?? Data(parameter.name.utf8))
                + field(3, bytes: Data(parameter.issuer.utf8))
                + field(4, int: parameter.algorithm)
                + field(5, int: parameter.digits)
                + field(6, int: parameter.type)
            payload += field(1, bytes: message)
        }
        payload += field(2, int: 1)
        if let batch {
            payload += field(3, int: batch.size) + field(4, int: batch.index) + field(5, int: batch.id)
        }
        var base64 = payload.base64EncodedString()
        if urlSafe {
            base64 = base64.replacingOccurrences(of: "+", with: "-").replacingOccurrences(of: "/", with: "_")
                .replacingOccurrences(of: "=", with: "")
        }
        let encoded = base64.addingPercentEncoding(withAllowedCharacters: .alphanumerics) ?? base64
        return "otpauth-migration://offline?data=\(encoded)"
    }

    // MARK: - Reading and writing

    private func check(_ name: String, _ generated: Any) throws {
        let url = Self.goldenDirectory.appendingPathComponent("\(name).json")
        let stored = try JSONSerialization.jsonObject(with: Data(contentsOf: url))
        // Round-trip through serialization once so Swift values match the NSNumber / NSNull representation in the file.
        let normalized = try JSONSerialization.jsonObject(with: JSONSerialization.data(withJSONObject: generated))
        XCTAssertTrue((normalized as AnyObject).isEqual(stored), "\(name).json does not match current Mac behavior")
    }
}

/// JSON uses null for absent values.
private func nullable(_ value: Any?) -> Any { value ?? NSNull() }

private extension Data {
    init(hex: String) {
        var bytes: [UInt8] = []
        var index = hex.startIndex
        while index < hex.endIndex {
            let next = hex.index(index, offsetBy: 2)
            bytes.append(UInt8(hex[index..<next], radix: 16)!)
            index = next
        }
        self.init(bytes)
    }

    var hex: String { map { String(format: "%02x", $0) }.joined() }
}
